const req = $('Dashboard: movement action').first().json.body || {};
const p = req.params || {};
const who = $('Verify caller').first().json;
const role = who.role;
const actor = 'dashboard:' + who.userId;
const bad = (error, code = 400) => [{ json: { valid: false, code, error } }];
const ok = (rpc, body, note) => [{ json: { valid: true, rpc, body, note } }];
const s = (v) => String(v == null ? '' : v).trim();
const only = (...roles) => roles.includes(role);
const FLOOR = ['admin', 'manager', 'warehouse'];
const PRODUCER_SIDE = ['received_by_producer', 'production_started', 'production_complete', 'awaiting_return', 'return_dispatched'];
switch (req.action) {
  case 'upsert_producer':
    if (!only('admin', 'manager')) return bad('Only a manager or admin can add or change producers.', 403);
    if (!p.producer || typeof p.producer !== 'object') return bad('Producer details are required.');
    return ok('flow_mv_upsert_producer', { p: p.producer, p_actor: actor }, 'Producer saved.');
  case 'set_rate':
    if (!only('admin', 'manager')) return bad('Only a manager or admin can change a rate card.', 403);
    if (!p.producer_id) return bad('Choose a producer.');
    return ok('flow_mv_set_rate', { p_producer: p.producer_id, p_method: s(p.method), p_basis: s(p.basis), p_unit_price: Number(p.unit_price), p_setup_fee: Number(p.setup_fee || 0), p_min_job: Number(p.min_job_charge || 0), p_notes: s(p.notes) || null, p_actor: actor }, 'Rate saved. The producer selection engine will use it from the next recommendation.');
  case 'create_movement':
    if (!only(...FLOOR, 'production')) return bad('Your role cannot create producer movements.', 403);
    if (!p.producer_id) return bad('Choose a producer.');
    if (!Array.isArray(p.items) || !p.items.length) return bad('Choose at least one line to send.');
    return ok('flow_create_outbound_movement', { p_producer: p.producer_id, p_items: p.items.map((i) => ({ order_line_id: i.order_line_id, qty: Number(i.qty) })), p_actor: actor, p_type: s(p.type) || 'outbound_to_producer', p_carrier: s(p.carrier) || null, p_notes: s(p.notes) || null }, 'Consignment created. Pick it, pack it and print its labels next.');
  case 'scan': {
    if (!s(p.code) || !s(p.event)) return bad('A movement and an event are required.');
    const ev = s(p.event);
    if (PRODUCER_SIDE.includes(ev)) { if (!only(...FLOOR, 'production')) return bad('Your role cannot record producer steps.', 403); }
    else if (!only(...FLOOR)) return bad('Your role cannot pick, pack or dispatch consignments.', 403);
    const payload = Object.assign({}, p.payload || {});
    if (PRODUCER_SIDE.includes(ev) && !s(payload.note)) payload.note = 'Recorded by ' + role + ' on the producer’s behalf';
    return ok('flow_tp_scan', { p_movement: s(p.code), p_event: ev, p_actor: actor, p_payload: payload }, 'Recorded.');
  }
  case 'record_return':
    if (!only(...FLOOR)) return bad('Your role cannot book a return in.', 403);
    if (!s(p.code) || !Array.isArray(p.items) || !p.items.length) return bad('Enter what came back.');
    return ok('flow_tp_record_return', { p_movement: s(p.code), p_items: p.items, p_actor: actor, p_payload: p.payload || {} }, 'Return recorded. Any shortage is now tracked as a discrepancy.');
  case 'check_return':
    if (!only(...FLOOR)) return bad('Your role cannot check returned goods.', 403);
    if (!s(p.code) || !Array.isArray(p.items) || !p.items.length) return bad('Enter the check result.');
    return ok('flow_tp_check_return', { p_movement: s(p.code), p_items: p.items, p_actor: actor, p_payload: p.payload || {} }, 'Check recorded.');
  case 'direct_dispatch':
    if (!only(...FLOOR)) return bad('Your role cannot confirm direct dispatch.', 403);
    return ok('flow_tp_direct_dispatch', { p_movement: s(p.code), p_tracking: s(p.tracking), p_carrier: s(p.carrier), p_pod: p.pod || {}, p_actor: actor }, 'Direct dispatch recorded.');
  case 'resolve_discrepancy':
    if (!only('admin', 'manager')) return bad('Only a manager or admin can resolve a producer discrepancy.', 403);
    if (!p.id || s(p.note).length < 3) return bad('A resolution and a note are required.');
    return ok('flow_tp_resolve_discrepancy', { p_id: p.id, p_resolution: s(p.resolution), p_note: s(p.note), p_actor: actor }, 'Discrepancy resolved.');
  case 'cancel_movement':
    if (!only(...FLOOR)) return bad('Your role cannot cancel a consignment.', 403);
    return ok('flow_mv_cancel_movement', { p_movement: s(p.code), p_actor: actor, p_reason: s(p.reason) }, 'Consignment cancelled. The units are free to send again.');
  default:
    return bad('Unknown action.');
}
